<?php
declare(strict_types=1);
function runHistoricalPaymentCases(PDO $db,callable $q,callable $reset,callable $pair,callable $hash,array $users,string $dir):void
{
    $reset();$actor=$users['admin'];$a=$pair(['payer'=>'Parent Example','signer'=>'Parent Example','student'=>'Child Other','relationship'=>'Mother','dob'=>'2015-01-01']);$a['record']=$q('SELECT source_record_id FROM cognito_waivers WHERE id=?',[$a['wid']])->fetchColumn();$input=consolidatedFixture([[$a]],['Child Other']);$service=new ConsolidatedReconciliation($db);$before=$hash();$p=$service->preview($actor,$input);
    bulkCheck($p['summary']['new_people_proposed']===1&&$p['summary']['groups_ready']===1&&$p['summary']['household_payer_relationships_proposed']===1&&$before===$hash(),'unapproved household proposal does not block a separate child person proposal');
    $q("UPDATE identity_match_candidates SET match_reason='manual_review_pending' WHERE id=?",[$a['ids']['signer']]);$p=$service->preview($actor,$input);bulkCheck($p['summary']['groups_ready']===0,'existing manual hold remains protected');$q("UPDATE identity_match_candidates SET match_reason='review_signals' WHERE id=?",[$a['ids']['signer']]);
    $known=(new People($db))->create('Parent','Example');(new IdentityAssociations($db))->decide('stripe','customer',$a['external'],'customer',(int)$known['id'],'confirmed',$actor);
    $q("INSERT INTO stripe_customers(stripe_customer_id,name) VALUES ('cus_HouseholdConflict','Different Adult')");$input['groups'][0]['Stripe customer ID(s)'].=' | cus_HouseholdConflict';
    $studentOnly=['BMA-W-0001'=>['student_verified'=>true]];$p=$service->preview($actor,$input,$studentOnly);bulkCheck($p['groups']['BMA-W-0001']['apply_ready']&&in_array('COMPETING_PAYER_NAMES',$p['groups']['BMA-W-0001']['household_issues'],true),'student-only approval remains eligible while payer-name conflict stays unresolved');
    $withPayer=['BMA-W-0001'=>['student_verified'=>true,'payer_student_verified'=>true]];$guard=$service->preview($actor,$input,$withPayer);bulkCheck(!$guard['groups']['BMA-W-0001']['apply_ready'],'explicit household approval remains blocked by conflicting payer evidence');
    $r=$service->apply($actor,$input,$studentOnly,$p['digest'],'Synthetic backup');bulkCheck($r['people_created']===1&&(int)$q('SELECT COUNT(*) FROM person_relationships')->fetchColumn()===0&&$q("SELECT person_id FROM stripe_customers WHERE stripe_customer_id='cus_HouseholdConflict'")->fetchColumn()===null,'student-only apply creates no payer associations relationships or memberships');
    $reset();
    $folder=$dir.'/historical';mkdir($folder,0700);$headers=['id','PaymentIntent ID','Amount','Amount Refunded','Currency','Status','Captured','Created date (UTC)','Customer ID','Invoice ID','Mode','Card ID','Unknown column'];
    $base=['Amount'=>'13.00','Amount Refunded'=>'0.00','Currency'=>'usd','Status'=>'paid','Captured'=>'true','Created date (UTC)'=>'2026-01-01 12:00:00','Mode'=>'Live','Card ID'=>'DO_NOT_STORE_12345','Unknown column'=>'DO_NOT_STORE_12345'];
    $existing=['id'=>'ch_HistoryExisting','PaymentIntent ID'=>'pi_HistoryExisting']+$base;$new=['id'=>'py_HistoryNew','PaymentIntent ID'=>'pi_HistoryNew']+$base;$attempt=['id'=>'','PaymentIntent ID'=>'pi_HistoryAttempt','Status'=>'canceled','Captured'=>'false']+$base;
    $write=function(array $rows)use($folder,$headers){$f=fopen($folder.'/'.HistoricalPaymentPreview::FILENAME,'wb');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,$headers,',','"','');foreach($rows as $row)fputcsv($f,array_map(fn($h)=>$row[$h]??'',$headers),',','"','');fclose($f);return HistoricalPaymentPreview::read($folder);};
    $q("INSERT INTO stripe_transactions(stripe_charge_id,amount_minor,amount_refunded_minor,currency,status,captured,stripe_created_at) VALUES ('ch_HistoryExisting',1300,0,'usd','paid',1,'2026-01-01 12:00:00')");$q("UPDATE stripe_source_identity SET stripe_account_id='acct_HistoryFixture',stripe_livemode=1,established_at=UTC_TIMESTAMP(6) WHERE id=1");
    $source=$write([$existing,$new,$new,$attempt]);$before=$hash();$coverage=(new HistoricalPaymentPreview($db))->preview(['pi_HistoryExisting','pi_HistoryNew','pi_HistoryMissing'],$source);$c=$coverage['summary'];
    bulkCheck($c['historical_existing_charge_records']===1&&$c['historical_identifier_enrichments_proposed']===1&&$c['payment_identifiers_found_in_existing_storage']===1,'export charge/PaymentIntent pair resolves an existing charge without changing it');
    bulkCheck($c['historical_transactions_available_for_backfill']===1&&$c['historical_duplicate_rows']===1&&$c['historical_attempts_without_charge']===1&&$c['remaining_missing_payments']===1,'historical preview deduplicates stable charge IDs and excludes non-charge attempts');
    bulkCheck($before===$hash()&&!str_contains(json_encode(array_map(fn($r)=>$r['record']->values(),$source['records'])),'DO_NOT_STORE_12345'),'historical preview makes no writes and filters ignored/unknown values');
    $conflict=$write([array_replace($existing,['Amount'=>'14.00']),$new]);$c=(new HistoricalPaymentPreview($db))->preview(['pi_HistoryExisting'],$conflict)['summary'];bulkCheck($c['historical_conflicting_records']===1&&$c['remaining_missing_payments']===1,'changed historical amounts require review and never overwrite existing transactions');
    $q('UPDATE stripe_source_identity SET stripe_livemode=0 WHERE id=1');$c=(new HistoricalPaymentPreview($db))->preview(['pi_HistoryNew'],$source)['summary'];bulkCheck($c['historical_environment_conflict']===1&&$c['historical_transactions_available_for_backfill']===0,'test/live source mismatch cannot become a backfill proposal');$q('UPDATE stripe_source_identity SET stripe_livemode=1 WHERE id=1');
    $q("DELETE FROM stripe_transactions WHERE stripe_charge_id='ch_HistoryExisting'");
    if($actual=getenv('BMA_CONSOLIDATED_TEST_INPUT_DIR')){$source=HistoricalPaymentPreview::read($actual);$input=ConsolidatedInputs::read($actual);$before=$hash();$p=$service->preview($actor,$input,[],$source);$c=$p['payment_coverage']['summary'];bulkCheck($c['historical_rows_read']===1450&&$c['historical_identifiable_transactions']===1277&&$c['referenced_historical_payments_available_for_backfill']===427&&$c['remaining_missing_payments']===0&&$before===$hash(),'actual historical export contains all 427 referenced payments and preview changes no database rows');}
}
